<template>
  <div class="back-white" :class="{ 'embedded-mode': embedded }" id="access_control_detail" v-if="renderComponent && currentPermissions?.fields" >

    <div class="embedded-header back-white">
      <div class="embedded-header-content">
        <h3 class="embedded-title">
          {{ $t('field_permissions') }}
          <span class="embedded-subtitle">({{ $t('configure_field_access_for') }} <span class="doc-name-highlight">{{ formatDocId }}</span>)</span>
        </h3>
      </div>
      <div class="embedded-header-actions">
        <f-btn :label="$t('save')" @click="save()" />
        <button class="close-btn" @click="$emit('close')">
          <q-icon name="close" size="20px" />
        </button>
      </div>
    </div>

    <!-- Tabs Navigation -->
    <q-tabs
      v-model="activeTab"
      dense
      active-class="highlighted-back"
      indicator-color="primary"
      active-color="primary"
      align="left"
      class="field-tabs-container"
    >
      <q-tab name="table_columns" :label="$t('table_columns')" />
      <template v-for="fields in field_setting" :key="fields.name">
        <q-tab :name="fields.name" :label="$t(`${fields.name}`)" />
      </template>
    </q-tabs>
    <q-separator />

    <!-- Fields Content -->
    <div class="fields-content">
      <!-- Table Columns Tab -->
      <div v-if="activeTab === 'table_columns'" class="fields-grid">
        <div
          v-for="columns in table_columns"
          :key="columns.column_name"
          class="field-item"
        >
          <div class="field-info">
            <div class="field-name">{{ columns?.column_name }}</div>
            <div class="field-key">[{{ columns?.column_name }}]</div>
          </div>
          <div class="field-control">
            <q-select
              v-model="apiData[group_id][doc_id]['fields'][columns.id]"
              :options="fieldPropertiesOptions"
              :class="getFieldSelectClass(apiData[group_id][doc_id]['fields'][columns.id])"
              borderless
              dense
              emit-value
              map-options
              hide-dropdown-icon
              options-dense
            >
              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>
                      <q-icon
                        v-if="scope.opt.value === apiData[group_id][doc_id]['fields'][columns.id]"
                        name="check"
                        class="q-mr-sm"
                        color="primary"
                      />
                      {{ scope.opt.label }}
                    </q-item-label>
                  </q-item-section>
                </q-item>
              </template>
            </q-select>
          </div>
        </div>
      </div>

      <!-- Dynamic Field Setting Tabs -->
      <template v-for="fieldGroup in field_setting" :key="fieldGroup.name">
        <div v-if="activeTab === fieldGroup.name" class="fields-grid">
          <template v-for="(field, index) in fieldGroup?.rows" :key="index">
            <div
              v-for="row in field"
              :key="row.id"
              class="field-item"
            >
              <div class="field-info">
                <div class="field-name">{{ row.title }}</div>
                <div class="field-key">[{{ row?.field_name }}]</div>
              </div>
              <div class="field-control">
                <q-select
                  v-model="apiData[group_id][doc_id]['fields'][row.id]"
                  :options="fieldPropertiesOptions"
                  :class="getFieldSelectClass(apiData[group_id][doc_id]['fields'][row.id])"
                  borderless
                  dense
                  emit-value
                  map-options
                  hide-dropdown-icon
                  options-dense
                >
                  <template v-slot:option="scope">
                    <q-item v-bind="scope.itemProps">
                      <q-item-section>
                        <q-item-label>
                          <q-icon
                            v-if="scope.opt.value === apiData[group_id][doc_id]['fields'][row.id]"
                            name="check"
                            class="q-mr-sm"
                            color="primary"
                          />
                          {{ scope.opt.label }}
                        </q-item-label>
                      </q-item-section>
                    </q-item>
                  </template>
                </q-select>
              </div>
            </div>
          </template>
        </div>
      </template>
    </div>
  </div>

  <!-- Loading state for embedded mode -->
  <div v-else-if="embedded && documentKey && !renderComponent" class="empty-state-container back-white">
    <q-spinner-dots color="primary" size="40px" />
  </div>

  <!-- Empty state for embedded mode when no document selected -->
  <div v-else-if="embedded && !documentKey" class="empty-state-container back-white">
    <div class="empty-state">
      <q-icon name="touch_app" size="48px" color="grey-5" />
      <p>{{ $t('select_document_to_configure') }}</p>
    </div>
  </div>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import {
  docFieldsApiService,
  documentPermissionsApiService,
  documentTypeApiService,
} from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import helperUtil from 'src/utils/helperUtil';
import helperMixin from 'src/mixins/helperMixin.js';
import { useDocPermissionsStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { getOrgId } from 'src/utils/organization/org_id_helper';
export default defineComponent({
  el: '#app',
  mixins: [helperUtil, helperMixin],
  props: {
    // Props for embedded mode
    embedded: {
      type: Boolean,
      default: false,
    },
    documentKey: {
      type: String,
      default: '',
    },
    groupIdProp: {
      type: String,
      default: '',
    },
    groupNameProp: {
      type: String,
      default: '',
    },
  },
  emits: ['close'],
  async mounted() {
    // In embedded mode, only initialize if a document is selected
    if (!this.embedded || this.documentKey) {
      await this.init();
    }
  },
  watch: {
    // Watch for document changes in embedded mode
    documentKey: {
      immediate: false,
      async handler(newVal) {
        if (this.embedded) {
          if (newVal) {
            this.doc_id = newVal;
            this.renderComponent = false;
            await this.init();
          } else {
            // Reset when document is deselected (close button)
            this.renderComponent = false;
          }
        }
      },
    },
  },
  components: {
    Loader,
  },
  computed: {
    formatDocId() {
      const org_id = getOrgId();
      const doc_id: string = this.doc_id;
      if (doc_id.includes(org_id)) {
        return doc_id.replace('_' + org_id, '').replace(/_/g, ' ');
      }
      return doc_id.replace(/_/g, ' ');
    },
    formatGroupName(): string {
      return this.group_name.replace(/_/g, ' ');
    },
    currentPermissions(): dynamicObj | null {
      return this.apiData[this.group_id]?.[this.doc_id] ?? null;
    },
  },
  methods: {
    async init() {
      this.showLoading();
      try {
        await this.getTableColumns();
        await this.getFields();
        await this.accessDetail();
      } catch (error) {
      } finally {
        this.renderComponent = true;
        this.hideLoading();
      }
    },
    async updateDocTyleFields(data: any) {
      try {
        const formData = new FormData();
        formData.append('data', data);
        const rs =
          await documentPermissionsApiService.updateAllDocTypeSettings(
            formData,
          );
        if (rs.success === false) throw { message: rs.message };
      } catch (error) {
        throw error;
      }
    },
    async save() {
      this.showLoading();
      const data = JSON.stringify(this.apiData);
      try {
        await this.updateDocTyleFields(data);
        await this.accessDetail();
        notify.success(this.$t('save_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async accessDetail() {
      await this.getAllDocTypeFieldsForAccessControl(this.group_id);
      this.mappingValueForDetailFields();
    },
    mappingValueForDetailFields() {
      if (!this.apiData[this.group_id]) {
        this.apiData[this.group_id] = {};
      }
      if (!this.apiData[this.group_id][this.doc_id]) {
        this.apiData[this.group_id][this.doc_id] = {};
      }
      const data = this.apiData[this.group_id][this.doc_id];
      if (data) {
        (Array.isArray(this.fields) ? this.fields : []).forEach((items: any) => {
          if (data[items] === undefined) {
            data[items] = 0;
          }
        });
        if (data['fields'] === undefined) data['fields'] = {};
        (Array.isArray(this.field_setting) ? this.field_setting : []).forEach((group: any) => {
          (Array.isArray(group?.rows) ? group.rows : []).forEach((rows: any) => {
            (Array.isArray(rows) ? rows : []).forEach((row: any) => {
              if (data['fields'][row.id] === undefined) {
                data['fields'][row.id] = 2;
              }
            });
          });
        });
        if (!Array.isArray(this.table_columns)) return;
        this.table_columns.forEach((item: any) => {
          if (data['fields'][item.id] === undefined) {
            data['fields'][item.id] = 2;
          }
        });
      }
    },
    async getFields() {
      this.field_setting = [];
      const data = {
        doc_type: this.doc_id,
      };
      try {
        const response = await docFieldsApiService.getFieldSettingsByType(data);
        if (response.success === false) {
          throw response;
        }
        this.field_setting = Array.isArray(response.field_setting)
          ? response.field_setting
          : [];
      } catch (err: any) {
        throw err;
      }
    },
    async getTableColumns() {
      this.table_columns = [] as any[];
      try {
        const response = await documentTypeApiService.getTableColumns(
          this.doc_id,
        );
        if (response.success === false) {
          throw { message: response.data.message };
        }
        const columns = response?.data?.[this.doc_id + '_TABLE'];
        this.table_columns = Array.isArray(columns) ? columns : [];
      } catch (error) {}
    },
    getFieldSelectClass(value: number | undefined): string {
      // Field permission values:
      // 0 = No Access
      // 1 = Read Only
      // 2 = Read/Write
      // 16 = Approval
      switch (value) {
        case 2:
          return 'field-permission-select read-write';
        case 1:
          return 'field-permission-select read-only';
        case 16:
          return 'field-permission-select approval';
        case 0:
          return 'field-permission-select no-access';
        default:
          return 'field-permission-select read-write';
      }
    },
  },
  data() {
    return {
      activeTab: ref('table_columns'),
      table_columns: ref([] as any[]),
      field_setting: ref([] as any[]),
      renderComponent: ref<boolean>(false),
      // Use props in embedded mode, otherwise use route params
      group_id: (this.embedded ? this.groupIdProp : this.$route.params.id) as string,
      doc_id: (this.embedded ? this.documentKey : this.$route.params.doc_type) as string,
      group_name: (this.embedded ? this.groupNameProp : this.$route.params.group_name) as string,
      fieldPropertiesOptions: [
        {
          label: this.$t('read_write'),
          value: 2,
        },
        // {
        //   label: this.$t('read_owner_write'),
        //   value: 4,
        // },
        {
          label: this.$t('read_only'),
          value: 1,
        },
        // {
        //   label: this.$t('owner_read_owner_write'),
        //   value: 8,
        // },
        {
          label: this.$t('approval'),
          value: 16,
        },
        {
          label: this.$t('no_access'),
          value: 0,
        },
      ],
    };
  },
  setup() {
    const permission_store = useDocPermissionsStore();
    const { accessOptionList, listOption, processing, apiData, fields } =
      storeToRefs(permission_store);
    const { getAllDocTypeFieldsForAccessControl } = permission_store;
    return {
      accessOptionList,
      listOption,
      processing,
      apiData,
      fields,
      getAllDocTypeFieldsForAccessControl,
    };
  },
});
</script>
